import React, { useEffect, useState, useCallback } from 'react';
import { getAllOrders, updateOrderStatus } from './api';
import { useToast } from './Toast';

const STATUS_OPTIONS = ['pending','confirmed','shipped','delivered','cancelled'];
const STATUS_COLOR = {
  pending:   'yellow',
  confirmed: 'blue',
  shipped:   'blue',
  delivered: 'green',
  cancelled: 'red',
};

export default function Orders() {
  const [orders,  setOrders]  = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter,  setFilter]  = useState('all');
  const [detail,  setDetail]  = useState(null);
  const [updating, setUpdating] = useState(null);
  const toast = useToast();

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const r = await getAllOrders();
      setOrders(r.orders || []);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { load(); }, [load]);

  const displayed = filter === 'all' ? orders : orders.filter(o => o.status === filter);

  async function changeStatus(id, status) {
    setUpdating(id);
    try {
      await updateOrderStatus(id, status);
      toast(`Order #${id} → ${status}`, 'success');
      setOrders(prev => prev.map(o => o.id === id ? { ...o, status } : o));
      if (detail?.id === id) setDetail(d => ({ ...d, status }));
    } catch (e) {
      toast(e.message, 'error');
    } finally {
      setUpdating(null);
    }
  }

  return (
    <div style={styles.page}>
      <div style={styles.header}>
        <div>
          <h1 style={styles.h1}>Orders</h1>
          <p style={{ color:'var(--muted)', fontSize:13 }}>{orders.length} total orders</p>
        </div>
      </div>

      {/* Filter tabs */}
      <div style={styles.tabs}>
        {['all', ...STATUS_OPTIONS].map(f => (
          <button
            key={f}
            onClick={() => setFilter(f)}
            style={{
              ...styles.tab,
              ...(filter === f ? styles.tabActive : {}),
            }}
          >
            {f.charAt(0).toUpperCase() + f.slice(1)}
            {f !== 'all' && (
              <span style={styles.tabCount}>
                {orders.filter(o => o.status === f).length}
              </span>
            )}
          </button>
        ))}
      </div>

      {/* Table */}
      <div className="card" style={{ padding:0, marginTop:16 }}>
        <div className="table-wrap">
          <table>
            <thead>
              <tr>
                <th>Order #</th>
                <th>Customer</th>
                <th>Total</th>
                <th>Payment</th>
                <th>City</th>
                <th>Status</th>
                <th>Date</th>
                <th style={{ textAlign:'right' }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                <tr><td colSpan={8} style={{ textAlign:'center', padding:'40px 0' }}><span className="spinner" /></td></tr>
              ) : displayed.length === 0 ? (
                <tr><td colSpan={8}>
                  <div className="empty"><div className="empty-icon">🛒</div><p>No orders found</p></div>
                </td></tr>
              ) : displayed.map(o => (
                <tr key={o.id}>
                  <td style={{ fontWeight:700, color:'var(--accent)' }}>#{o.id}</td>
                  <td>
                    <div style={{ fontWeight:500 }}>{o.user_name || '—'}</div>
                    {o.email && <div style={{ fontSize:11, color:'var(--muted)', marginTop:2 }}>{o.email}</div>}
                  </td>
                  <td style={{ fontWeight:600 }}>${Number(o.total_amount).toFixed(2)}</td>
                  <td style={{ textTransform:'uppercase', fontSize:11, letterSpacing:'0.05em', color:'var(--muted)' }}>
                    {o.payment_method}
                  </td>
                  <td style={{ color:'var(--muted)' }}>{o.shipping_city || '—'}</td>
                  <td>
                    <span className={`badge badge-${STATUS_COLOR[o.status] || 'gray'}`}>
                      {o.status}
                    </span>
                  </td>
                  <td style={{ color:'var(--muted)', fontSize:12 }}>
                    {o.created_at ? new Date(o.created_at).toLocaleDateString() : '—'}
                  </td>
                  <td>
                    <div style={{ display:'flex', gap:6, justifyContent:'flex-end' }}>
                      <button className="btn btn-ghost btn-sm" onClick={() => setDetail(o)}>View</button>
                      <select
                        value={o.status}
                        onChange={e => changeStatus(o.id, e.target.value)}
                        disabled={updating === o.id}
                        style={styles.select}
                      >
                        {STATUS_OPTIONS.map(s => (
                          <option key={s} value={s}>{s.charAt(0).toUpperCase()+s.slice(1)}</option>
                        ))}
                      </select>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Order Detail Modal */}
      {detail && (
        <div className="overlay" onClick={e => e.target === e.currentTarget && setDetail(null)}>
          <div className="modal" style={{ maxWidth:540 }}>
            <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:20 }}>
              <h3 style={{ margin:0 }}>Order #{detail.id}</h3>
              <span className={`badge badge-${STATUS_COLOR[detail.status] || 'gray'}`}>
                {detail.status}
              </span>
            </div>

            {/* Shipping */}
            <div className="card" style={{ background:'var(--surface2)', marginBottom:16 }}>
              <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:'8px 16px' }}>
                <InfoRow label="Customer" value={detail.user_name || '—'} />
                <InfoRow label="Email"    value={detail.email || '—'} />
                <InfoRow label="Ship To"  value={detail.shipping_name || '—'} />
                <InfoRow label="City"     value={`${detail.shipping_city || '—'} ${detail.shipping_zip || ''}`} />
                <InfoRow label="Address"  value={detail.shipping_address || '—'} />
                <InfoRow label="Payment"  value={(detail.payment_method || '').toUpperCase()} />
              </div>
            </div>

            {/* Total */}
            <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', padding:'12px 16px', background:'rgba(201,169,110,0.08)', borderRadius:10, border:'1px solid rgba(201,169,110,0.15)', marginBottom:16 }}>
              <span style={{ fontSize:13, color:'var(--muted)' }}>Total Amount</span>
              <span style={{ fontFamily:"'Playfair Display',serif", fontSize:22, color:'var(--accent)' }}>
                ${Number(detail.total_amount).toFixed(2)}
              </span>
            </div>

            {/* Status update */}
            <div style={{ marginBottom:16 }}>
              <label className="label">Update Status</label>
              <select
                value={detail.status}
                onChange={e => changeStatus(detail.id, e.target.value)}
                disabled={updating === detail.id}
                className="input"
              >
                {STATUS_OPTIONS.map(s => (
                  <option key={s} value={s}>{s.charAt(0).toUpperCase()+s.slice(1)}</option>
                ))}
              </select>
            </div>

            <button className="btn btn-ghost" style={{ width:'100%', justifyContent:'center' }} onClick={() => setDetail(null)}>Close</button>
          </div>
        </div>
      )}
    </div>
  );
}

function InfoRow({ label, value }) {
  return (
    <div>
      <div style={{ fontSize:11, color:'var(--muted)', fontWeight:600, letterSpacing:'0.04em', marginBottom:3 }}>{label}</div>
      <div style={{ fontSize:13 }}>{value}</div>
    </div>
  );
}

const styles = {
  page: { padding:'28px 32px', maxWidth:1200 },
  header: { display:'flex', alignItems:'flex-start', justifyContent:'space-between', marginBottom:20 },
  h1: { fontFamily:"'Playfair Display', serif", fontSize:28, fontWeight:400, color:'var(--text)', marginBottom:4 },
  tabs: { display:'flex', gap:6, flexWrap:'wrap' },
  tab: {
    padding:'7px 14px', borderRadius:8, fontSize:12, fontWeight:500,
    background:'transparent', border:'1px solid var(--border)',
    color:'var(--muted)', cursor:'pointer', transition:'var(--transition)',
    fontFamily:'var(--font)', display:'flex', alignItems:'center', gap:6,
  },
  tabActive: {
    background:'rgba(201,169,110,0.12)', borderColor:'rgba(201,169,110,0.3)',
    color:'var(--accent)',
  },
  tabCount: {
    background:'rgba(255,255,255,0.08)', color:'var(--muted)',
    fontSize:10, fontWeight:700, padding:'2px 6px', borderRadius:99,
  },
  select: {
    background:'var(--surface2)', border:'1px solid var(--border)',
    borderRadius:7, padding:'5px 8px', color:'var(--text)',
    fontSize:12, fontFamily:'var(--font)', cursor:'pointer', outline:'none',
  },
};
